class Solution {
    public boolean checkPossibility(int[] nums) {
        int changes = 0;
        for (int i = 0; i + 1 < nums.length; i++) {
            if (nums[i] <= nums[i + 1]) {
                continue;
            }

            changes++;
            if (changes > 1) {
                return false;
            }

            if (i == 0 || nums[i - 1] <= nums[i + 1]) {
                nums[i] = nums[i + 1];
            } else {
                nums[i + 1] = nums[i];
            }
        }
        return true;
    }
}

class Solution {
    public boolean checkPossibility(int[] nums) {
        int violation = -1;
        for (int i = 0; i + 1 < nums.length; i++) {
            if (nums[i] > nums[i + 1]) {
                if (violation != -1) {
                    return false;
                }
                violation = i;
            }
        }

        if (violation == -1) {
            return true;
        }
        int i = violation;
        boolean canLowerLeft = i == 0 || nums[i - 1] <= nums[i + 1];
        boolean canRaiseRight = i + 1 == nums.length - 1 || nums[i] <= nums[i + 2];
        return canLowerLeft || canRaiseRight;
    }
}

class Solution {
    public boolean checkPossibility(int[] nums) {
        int n = nums.length;
        if (n <= 2) {
            return true;
        }

        boolean[] prefixOk = new boolean[n];
        boolean[] suffixOk = new boolean[n];
        prefixOk[0] = true;
        for (int i = 1; i < n; i++) {
            prefixOk[i] = prefixOk[i - 1] && nums[i - 1] <= nums[i];
        }
        if (prefixOk[n - 1]) {
            return true;
        }

        suffixOk[n - 1] = true;
        for (int i = n - 2; i >= 0; i--) {
            suffixOk[i] = suffixOk[i + 1] && nums[i] <= nums[i + 1];
        }

        for (int i = 0; i < n; i++) {
            boolean leftValid = i <= 1 || prefixOk[i - 1];
            boolean rightValid = i >= n - 2 || suffixOk[i + 1];
            if (!leftValid || !rightValid) {
                continue;
            }

            int lowerBound = i == 0 ? Integer.MIN_VALUE : nums[i - 1];
            int upperBound = i == n - 1 ? Integer.MAX_VALUE : nums[i + 1];
            if (lowerBound <= upperBound) {
                return true;
            }
        }
        return false;
    }
}

class Solution {
    public boolean checkPossibility(int[] nums) {
        int violation = -1;
        for (int i = 0; i + 1 < nums.length; i++) {
            if (nums[i] > nums[i + 1]) {
                violation = i;
                break;
            }
        }
        if (violation == -1) {
            return true;
        }

        return isNonDecreasingWithChange(nums, violation, nums[violation + 1])
            || isNonDecreasingWithChange(nums, violation + 1, nums[violation]);
    }

    private boolean isNonDecreasingWithChange(int[] nums, int changedIndex, int changedValue) {
        int previous = Integer.MIN_VALUE;
        for (int i = 0; i < nums.length; i++) {
            int current = i == changedIndex ? changedValue : nums[i];
            if (previous > current) {
                return false;
            }
            previous = current;
        }
        return true;
    }
}
